pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }
    function testFuzz_property(address from, address[] memory tos, uint v) public {
        vm.assume(from != address(this));
        vm.assume(tos.length > 0);
        ArgChecker checker = new ArgChecker(from);
        bool ok;
        try c.transfer(from, address(checker), tos, v) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

contract ArgChecker {
    address immutable expectedFrom;
    constructor(address _expectedFrom) { expectedFrom = _expectedFrom; }
    fallback(bytes calldata data) external payable returns (bytes memory) {
        address decodedFrom = abi.decode(data[4:], (address));
        require(decodedFrom == expectedFrom, "wrong from");
        return "";
    }
}
